            autoAttackDamage: finiteNumber(stats.autoAttackDamage, 0),
            criticalRate: finiteNumber(stats.criticalRate, 0),
            criticalDamage: finiteNumber(stats.criticalDamage, 0),
            taskDamage: finiteNumber(stats.taskDamage, 0),
